1: /* PT Contoh — company profile */
2: :root {
3:   --primary: #1d4ed8;
4:   --primary-dark: #1e3a8a;
5:   --bg: #f8fafc;
6:   --surface: #ffffff;
7:   --text: #0f172a;
8:   --muted: #64748b;
9:   --radius: 10px;
10: }
11: 
12: * { box-sizing: border-box; margin: 0; padding: 0; }
13: 
14: body {
15:   font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
16:   color: var(--text);
17:   background: var(--bg);
18:   line-height: 1.6;
19: }
20: 
21: .container { max-width: 1100px; margin: 0 auto; padding: 0 1.25rem; }
22: 
23: .site-header {
24:   position: sticky;
25:   top: 0;
26:   background: var(--surface);
27:   border-bottom: 1px solid #e2e8f0;
28:   z-index: 10;
29: }
30: 
31: .nav-wrap { display: flex; align-items: center; justify-content: space-between; height: 64px; }
32: 
33: .logo { font-size: 1.25rem; font-weight: 800; color: var(--primary); text-decoration: none; }
34: 
35: .nav { display: flex; gap: 1.25rem; flex-wrap: wrap; }
36: .nav a { color: var(--text); text-decoration: none; font-weight: 500; }
37: .nav a:hover { color: var(--primary); }
38: 
39: .hero {
40:   background: linear-gradient(135deg, var(--primary), var(--primary-dark));
41:   color: #fff;
42:   padding: 5rem 0;
43:   text-align: center;
44: }
45: .hero h1 { font-size: 2.25rem; margin-bottom: .75rem; }
46: .hero p { max-width: 600px; margin: 0 auto 1.5rem; opacity: .9; }
47: .hero .btn { background: #fff; color: var(--primary); }
48: 
49: .btn {
50:   display: inline-block;
51:   padding: .65rem 1.5rem;
52:   border: none;
53:   border-radius: var(--radius);
54:   background: var(--primary);
55:   color: #fff;
56:   font-size: 1rem;
57:   font-weight: 600;
58:   text-decoration: none;
59:   cursor: pointer;
60: }
61: .btn:hover { filter: brightness(1.1); }
62: 
63: .section { padding: 4rem 0; }
64: .section.alt { background: var(--surface); }
65: .section h2 { font-size: 1.75rem; margin-bottom: 1.5rem; }
66: 
67: .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; }
68: 
69: .card {
70:   background: var(--surface);
71:   border: 1px solid #e2e8f0;
72:   border-radius: var(--radius);
73:   padding: 1.5rem;
74: }
75: .section.alt .card { background: var(--bg); }
76: .card h3 { margin-bottom: .75rem; }
77: .card p { margin-bottom: .5rem; }
78: 
79: .facts { list-style: none; display: grid; gap: .5rem; }
80: 
81: /* Katalog produk */
82: .filters { display: flex; gap: .5rem; flex-wrap: wrap; margin-bottom: 1.5rem; }
83: 
84: .chip {
85:   padding: .4rem 1rem;
86:   border: 1px solid #cbd5e1;
87:   border-radius: 999px;
88:   background: var(--surface);
89:   color: var(--text);
90:   font-size: .9rem;
91:   cursor: pointer;
92: }
93: .chip.active { background: var(--primary); border-color: var(--primary); color: #fff; }
94: 
95: .grid-products {
96:   display: grid;
97:   grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
98:   gap: 1.25rem;
99: }
100: 
101: .product-card {
102:   background: var(--surface);
103:   border: 1px solid #e2e8f0;
104:   border-radius: var(--radius);
105:   overflow: hidden;
106:   display: flex;
107:   flex-direction: column;
108: }
109: .product-img {
110:   height: 150px;
111:   display: flex;
112:   align-items: center;
113:   justify-content: center;
114:   font-size: 3rem;
115:   background: #eef2ff;
116: }
117: .product-body { padding: 1rem; display: flex; flex-direction: column; gap: .35rem; flex: 1; }
118: .product-body h3 { font-size: 1.05rem; }
119: .product-cat { font-size: .8rem; color: var(--muted); text-transform: uppercase; letter-spacing: .03em; }
120: .product-price { font-weight: 700; color: var(--primary); margin-top: auto; }
121: .product-empty { grid-column: 1 / -1; color: var(--muted); text-align: center; padding: 2rem 0; }
122: 
123: /* Form kontak */
124: #contact-form { display: flex; flex-direction: column; gap: .5rem; }
125: #contact-form label { font-weight: 600; font-size: .9rem; margin-top: .5rem; }
126: #contact-form input,
127: #contact-form textarea {
128:   padding: .6rem .75rem;
129:   border: 1px solid #cbd5e1;
130:   border-radius: 8px;
131:   font: inherit;
132: }
133: #contact-form input:focus,
134: #contact-form textarea:focus { outline: 2px solid var(--primary); outline-offset: 1px; }
135: .form-status { min-height: 1.4em; font-size: .9rem; color: #15803d; }
136: .form-status.error { color: #b91c1c; }
137: 
138: .site-footer { background: var(--primary-dark); color: #c7d2fe; padding: 1.5rem 0; text-align: center; }
139: 
140: @media (max-width: 720px) {
141:   .grid-2 { grid-template-columns: 1fr; }
142:   .hero h1 { font-size: 1.75rem; }
143: }
