29:   for (const p of items) {
30:     const card = document.createElement("article");
31:     card.className = "product-card";
32: 
33:     const img = document.createElement("div");
34:     img.className = "product-img";
35:     img.setAttribute("aria-hidden", "true");
36:     img.textContent = p.emoji;
37: 
38:     const body = document.createElement("div");
39:     body.className = "product-body";
40: 
