46:     title.textContent = p.nama;
47: 
48:     const desc = document.createElement("p");
49:     desc.textContent = p.desc;
50: 
51:     const price = document.createElement("p");
52:     price.className = "product-price";
53:     price.textContent = formatRupiah(p.harga);
54: 
55:     body.append(cat, title, desc, price);
56:     card.append(img, body);
57:     grid.appendChild(card);
58:   }
59: }
